mapper.select:
select *
from order_express
where `status` = #{status}
  and refund_tx_status = #{txStatus}
limit 50

select oe.*
from order_express oe
left join goods_spu spu on spu.goods_id = oe.goods_id
left join goods_sku sku on sku.sku_id = oe.sku_id


        and oe.seller_address = #{sellerAddress}


        and oe.buyer_address = #{buyerAddress}


        and oe.`status` = #{status}


        and oe.delete_status = #{deleteStatus}


        and (
        oe.order_id = #{vague}
        or oe.seller_address = #{vague}
        or oe.buyer_address = #{vague}
        or oe.goods_id = #{vague}
        or oe.sku_id = #{vague}
        or oe.tx_hash = #{vague}
        or oe.refund_tx_hash = #{vague}
        or spu.name like CONCAT('%', #{vague}, '%')
        or sku.name like CONCAT('%', #{vague}, '%')
        or sku.token_name like CONCAT('%', #{vague}, '%')
        )


order by oe.order_id desc
